import { readFile } from "node:fs/promises";
import { Type, type Static } from "typebox";
import { Value } from "typebox/value";
import { normalizeTags } from "./tags.ts";

export const TaskSchema = Type.Object({
  taskId: Type.String({ minLength: 1 }),
  scenario: Type.String({ minLength: 1 }),
  prompt: Type.String({ minLength: 1 }),
  /** Model override as "provider/modelId". Default: pi settings. */
  model: Type.Optional(Type.String({ pattern: "^[^/]+/.+$" })),
  thinkingLevel: Type.Optional(
    Type.Union([
      Type.Literal("off"),
      Type.Literal("minimal"),
      Type.Literal("low"),
      Type.Literal("medium"),
      Type.Literal("high"),
      Type.Literal("xhigh"),
      Type.Literal("max"),
    ]),
  ),
  /** Session tags (see src/shared/tags.ts), recorded in the session file; normalized on load. */
  tags: Type.Optional(Type.Array(Type.String())),
});
export type Task = Static<typeof TaskSchema>;

export async function loadTask(path: string): Promise<Task> {
  let raw: unknown;
  try {
    raw = JSON.parse(await readFile(path, "utf8"));
  } catch (err) {
    throw new Error(`Cannot read task file ${path}: ${(err as Error).message}`);
  }
  if (!Value.Check(TaskSchema, raw)) {
    const errors = Value.Errors(TaskSchema, raw).map((e) => `${e.instancePath} ${e.message}`);
    throw new Error(`Invalid task file:\n${errors.join("\n")}`);
  }
  if (raw.tags) {
    try {
      raw.tags = normalizeTags(raw.tags);
    } catch (err) {
      throw new Error(`Invalid task file:\n/tags ${(err as Error).message}`);
    }
  }
  return raw;
}

import { PROJECT_FLAG, PROJECT_READ, SCENARIO_FLAG, SUBMIT_RESULT } from "../shared/protocol.ts";
import { TAGS_FLAG } from "../shared/tags.ts";
import type { Scenario } from "../shared/scenarios/index.ts";
import { TOOL_REF_TOOLS } from "../shared/tool-ref.ts";
import type { Task } from "../shared/task.ts";

const CODEMODE = "codemode";

export interface PiCommandOptions {
  task: Task;
  scenario: Scenario;
  /** Bundled runner extension (dist/extension.js). */
  extensionPath: string;
  /** Bundled scenario profile extension (dist/scenario-profile.js): system prompt, tools, skills. */
  scenarioProfileExtensionPath: string;
  /** Bundled project context extension (dist/project.js). Always loaded: it also adds AGENTS.md. */
  projectExtensionPath: string;
  /** Bundled metrics extension (dist/metrics.js): writes pi-agent.metrics entries. */
  metricsExtensionPath: string;
  /** Bundled tags extension (dist/tags.js): records the task's tags in the session file. */
  tagsExtensionPath: string;
  /** Bundled tool-ref extension (dist/tool-ref.js): tool-call handles. Loaded last (see its load-order check). */
  toolRefExtensionPath: string;
  /** Folder with a validated project.yaml (local project). */
  projectDir?: string;
  /** Remote project (from settings.json): the agent reads its files with project_read. */
  projectRead?: boolean;
  /** Skill directories to load (absolute; shared, the scenario's, then its included external skills). */
  skillPaths: string[];
  sessionDir: string;
  /** Previous session file to fork from. */
  resumeFrom?: string;
}

/**
 * pi CLI arguments for one scenario run. Loads nothing implicitly: no discovered extensions,
 * skills, prompt templates, context files, themes, MCP or project config (the workdir is not
 * trusted). Only the runner, scenario profile, project, metrics, tags and tool-ref extensions (tool-ref
 * last: no later extension may replace tool results and drop its trailers), the given skills
 * and the scenario's tools. The system prompt comes from the scenario profile extension (`--scenario`),
 * which also applies the tools and skills in-process; `--tools` and `--skill` stay as the hard
 * limits. Context files (AGENTS.md) come from the project extension, after skills, not from pi (`-nc`).
 * `-ne` also turns off pi's built-in extensions, so a scenario with the `codemode` tool loads
 * `builtin:codemode` explicitly (first, as pi loads built-ins). Its mode (`codemode.mode`) comes
 * from the settings in the agent dir.
 */
export function piArgs(o: PiCommandOptions): string[] {
  const { task, scenario } = o;
  return [
    "--mode", "json",
    "-ne",
    ...(scenario.tools.includes(CODEMODE) ? ["-e", `builtin:${CODEMODE}`] : []),
    "-e", o.extensionPath, "-e", o.scenarioProfileExtensionPath,
    "-e", o.projectExtensionPath, "-e", o.metricsExtensionPath,
    "-e", o.tagsExtensionPath, "-e", o.toolRefExtensionPath,
    "--no-mcp",
    "-ns", ...o.skillPaths.flatMap((p) => ["--skill", p]),
    "-np",
    "-nc",
    "--no-themes",
    "-na",
    "--offline",
    "--session-dir", o.sessionDir,
    ...(o.resumeFrom ? ["--fork", o.resumeFrom] : []),
    "--tools", [...scenario.tools, SUBMIT_RESULT, ...TOOL_REF_TOOLS, ...(o.projectRead ? [PROJECT_READ] : [])].join(","),
    ...(task.model ? ["--model", task.model] : []),
    ...(task.thinkingLevel ? ["--thinking", task.thinkingLevel] : []),
    `--${SCENARIO_FLAG}`, scenario.name,
    ...(o.projectDir ? [`--${PROJECT_FLAG}`, o.projectDir] : []),
    ...(task.tags?.length ? [`--${TAGS_FLAG}`, task.tags.join(",")] : []),
    "--", task.prompt,
  ];
}

/** Shell-quoted command line, for logs and for re-running a run by hand. */
export function shellQuote(argv: string[]): string {
  return argv.map((a) => (/^[\w@%+=:,./-]+$/.test(a) ? a : `'${a.replaceAll("'", `'\\''`)}'`)).join(" ");
}

import { existsSync } from "node:fs";
import { realpath } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { parseArgs } from "node:util";
import { getScenario, scenarioNames } from "../shared/scenarios/index.ts";
import { loadTask } from "../shared/task.ts";
import { resolveProject } from "./project-input.ts";
import { loadJustCommands } from "../shared/just.ts";
import { writeReport } from "./report-file.ts";
import { loadPreviousSession } from "./resume.ts";
import { runTask, type RunOptions } from "./run.ts";
import { resolveSkills, withExternalSkills } from "./skills.ts";

const EXIT_OK = 0; // report.json written (whatever its status)
const EXIT_CRASH = 1; // wrapper crashed; no reliable report
const EXIT_INPUT = 2; // invalid input

const USAGE =
  "usage: pi-agent run --task task.json [--workdir dir] [--out dir] [--resume session.jsonl] [--project dir]";

/**
 * Where the extensions and the app root (with skills/) are. Bundled: dist/pi-agent.js next to
 * dist/extension.js, dist/scenario-profile.js, dist/project.js, dist/metrics.js, dist/tags.js and dist/tool-ref.js. From source
 * (node src/wrapper/main.ts): pi loads the .ts extensions, which import .md files, so pi needs the same loader hook as `npm run dev`.
 */
function locate(): {
  extensionPath: string;
  scenarioProfileExtensionPath: string;
  projectExtensionPath: string;
  metricsExtensionPath: string;
  tagsExtensionPath: string;
  toolRefExtensionPath: string;
  rootDir: string;
} {
  const here = dirname(fileURLToPath(import.meta.url));
  const bundled = join(here, "extension.js");
  if (existsSync(bundled)) {
    return {
      extensionPath: bundled,
      scenarioProfileExtensionPath: join(here, "scenario-profile.js"),
      projectExtensionPath: join(here, "project.js"),
      metricsExtensionPath: join(here, "metrics.js"),
      tagsExtensionPath: join(here, "tags.js"),
      toolRefExtensionPath: join(here, "tool-ref.js"),
      rootDir: dirname(here),
    };
  }
  // Inherited by pi (and so by the commands its bash tool runs; source runs only).
  const hook = `--import=${pathToFileURL(resolve(here, "../../scripts/md-loader.mjs")).href}`;
  if (!process.env.NODE_OPTIONS?.includes(hook)) {
    process.env.NODE_OPTIONS = [process.env.NODE_OPTIONS, hook].filter(Boolean).join(" ");
  }
  return {
    extensionPath: join(here, "../extension/index.ts"),
    scenarioProfileExtensionPath: join(here, "../scenario-profile/index.ts"),
    projectExtensionPath: join(here, "../project/index.ts"),
    metricsExtensionPath: join(here, "../metrics/index.ts"),
    tagsExtensionPath: join(here, "../tags/index.ts"),
    toolRefExtensionPath: join(here, "../tool-ref/index.ts"),
    rootDir: resolve(here, "../.."),
  };
}

async function parseInput(argv: string[]): Promise<Omit<RunOptions, "signal" | "log">> {
  const { values, positionals } = parseArgs({
    args: argv,
    options: {
      task: { type: "string" },
      workdir: { type: "string" },
      out: { type: "string" },
      resume: { type: "string" },
      project: { type: "string" },
    },
    allowPositionals: true,
    strict: true, // unknown flags are an error
  });
  // The "run" subcommand is optional; anything else is an error.
  if (positionals.length > 1 || (positionals[0] !== undefined && positionals[0] !== "run")) {
    throw new Error(`Unknown command: ${positionals.join(" ")}`);
  }
  if (!values.task) throw new Error("--task is required");

  // pi records the real path as the session cwd (e.g. /private/tmp on macOS).
  const workdir = await realpath(resolve(values.workdir ?? process.cwd())).catch(() => {
    throw new Error(`Workdir ${values.workdir} does not exist`);
  });
  const out = resolve(values.out ?? `${workdir}/.agent-out`);
  const task = await loadTask(values.task);
  const scenario = getScenario(task.scenario);
  const resume = values.resume ? await loadPreviousSession(resolve(values.resume)) : undefined;
  const { project, warnings } = await resolveProject({ flag: values.project, workdir });
  // Invalid justfiles are invalid input, like an invalid project.yaml.
  const just = await loadJustCommands({ cwd: workdir, project });
  const { rootDir, ...extensions } = locate();
  const skillPaths = withExternalSkills(
    await resolveSkills(join(rootDir, "skills"), scenario.name, scenarioNames()),
    scenario.externalSkills?.include,
  );
  return {
    task, scenario, workdir, out, resume, project, just, warnings, skillPaths,
    piBin: process.env.PI_AGENT_PI_BIN || "pi",
    ...extensions,
  };
}

let input: Awaited<ReturnType<typeof parseInput>>;
try {
  input = await parseInput(process.argv.slice(2));
} catch (err) {
  console.error(`${(err as Error).message}\n${USAGE}`);
  process.exit(EXIT_INPUT);
}

// SIGINT/SIGTERM stop pi but still produce a report (status "error"). A second one exits now.
const controller = new AbortController();
for (const sig of ["SIGINT", "SIGTERM"] as const) {
  process.on(sig, () => {
    if (controller.signal.aborted) process.exit(EXIT_CRASH);
    console.error(`\n[pi-agent] ${sig}: stopping pi`);
    controller.abort();
  });
}

try {
  const report = await runTask({ ...input, signal: controller.signal });
  const path = await writeReport(input.out, report);
  console.error(`[pi-agent] status=${report.status} report=${path}`);
  console.log(path);
  process.exit(EXIT_OK);
} catch (err) {
  console.error(`[pi-agent] crashed: ${(err as Error).stack ?? err}`);
  process.exit(EXIT_CRASH);
}

